const f = $input.first().json;
const name = String(f['Full Name'] || '').trim();
const email = String(f['Email'] || '').trim().toLowerCase();
const course = String(f['Course'] || '').trim();
const score = Number(f['Score']);
const slug = s => s.toLowerCase().replace(/[^a-z0-9\u0600-\u06FF]+/g, '-').replace(/^-|-$/g, '');
let error = '';
if (!name) error = 'Missing name';
else if (!/^\S+@\S+\.\S+$/.test(email)) error = 'Invalid email';
else if (isNaN(score) || score < 60 || score > 100) error = 'Score must be between 60 and 100';
return [{ json: { cert_id: slug(email) + '_' + slug(course), name, email, course, score,
  valid: error === '', error, mode: 'issue' } }];

const now = Date.now();
const MAX_BATCH = 20;
return $input.all().map(i => i.json)
  .filter(r => {
    const state = String(r.status ?? '').trim().toLowerCase();
    const created = Date.parse(String(r.created_at ?? ''));
    return r.cert_id && ['pending', 'failed'].includes(state) &&
      (!Number.isFinite(created) || (now - created) / 60000 > 15);
  })
  .slice(0, MAX_BATCH)
  .map(r => ({ json: { cert_id: r.cert_id, name: r.name, email: r.email,
    course: r.course, score: r.score, mode: 'issue' } }));
// 'sending' and 'delivery_unknown' are intentionally excluded; review them manually.

const TEMPLATE_VERSION = 'v2';
const COURSE = ''; // Optional course filter
return $input.all().map(i => i.json)
  .filter(r => r.cert_id && String(r.status ?? '').trim().toLowerCase() === 'issued' &&
    String(r.template_version ?? '').trim() !== TEMPLATE_VERSION &&
    (!COURSE || r.course === COURSE))
  .slice(0, 20)
  .map(r => ({ json: { cert_id: r.cert_id, name: r.name, email: r.email,
    course: r.course, score: r.score, mode: 'backfill' } }));

const since = Date.now() - 7 * 864e5;
const parseDate = v => {
  const s = String(v ?? '').trim();
  const legacy = s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (legacy) return Date.UTC(+legacy[3], +legacy[2] - 1, +legacy[1]);
  return Date.parse(s);
};
const rows = $input.all().map(i => i.json)
  .filter(r => String(r.status ?? '').trim().toLowerCase() === 'issued' &&
    Number.isFinite(parseDate(r.issued_at)) && parseDate(r.issued_at) > since)
  .map(r => ({ json: { cert_id: r.cert_id, name: r.name, email: r.email,
    course: r.course, score: r.score, issued_at: r.issued_at } }));
return rows.length ? rows : [{ json: { note: 'No certificates issued this week' } }];
